import { prisma, ensureInvoiceSupportSchema } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { redirect } from "next/navigation";
import { SettingsForm } from "./settings-form";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Database, Settings2, FileText, TicketPercent, MessageSquare, Gift, Image as ImageIcon, Store, Mail } from "lucide-react";
import { removeDuplicates } from "@/lib/dedup";
import { LandingPageForm } from "@/components/settings/landing-page-form";
import { getLandingPageSettings } from "./landing-page/actions";
import { ExtendedLandingPageSettings } from "@/components/settings/landing-page-form";
import { CompanySettingsForm } from "@/components/settings/company-settings-form";
import { LoadingLink } from "@/components/ui/loading-link";
import { SettingsWorkspace } from "@/components/settings/settings-workspace";

import { AnimatedPage } from "@/components/ui/animated-page";
import { hasPermission, PERMISSIONS } from "@/lib/permissions";

export default async function SettingsPage() {
  const session = await auth();
  const role = session?.user?.role || "VIEWER";
  
  if (!hasPermission(role, PERMISSIONS.SETTINGS_MANAGE)) {
    redirect("/");
  }

  const rawSettings = await prisma.setting.findMany();
  // Deduplicate settings by key
  const settings = removeDuplicates(rawSettings, 'key');
  
  const config = settings.reduce((acc, curr) => ({ ...acc, [curr.key]: curr.value }), {} as Record<string, string>);

  // Fetch Landing Page Settings
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const landingPageSettings = await getLandingPageSettings();

  // Ensure schema has export columns before querying CompanySettings
  await ensureInvoiceSupportSchema();

  // Fetch Company Settings
  const companySettings = await prisma.companySettings.findFirst();

  return (
    <AnimatedPage><div className="max-w-6xl mx-auto space-y-8">
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Settings</h2>
          <p className="text-muted-foreground">Manage your application settings and preferences.</p>
        </div>
      </div>

      <SettingsWorkspace
        modules={
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            <LoadingLink href="/settings/weekly-reports">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader><FileText className="h-8 w-8 mb-2 text-primary" /><CardTitle>Reports &amp; Email Alerts</CardTitle><CardDescription>Weekly business intelligence, branded PDFs, schedules and Zoho delivery history.</CardDescription></CardHeader>
              </Card>
            </LoadingLink>
            <LoadingLink href="/settings/codes">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <Database className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Code Management</CardTitle>
                  <CardDescription>Manage system codes and reference data.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>
            
            <LoadingLink href="/settings/invoice">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <FileText className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Invoice Settings</CardTitle>
                  <CardDescription>Configure invoice prefixes, terms, and tax settings.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>
            
            <LoadingLink href="/settings/packaging">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <FileText className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Packaging Settings</CardTitle>
                  <CardDescription>Configure branding and label fields for packaging.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/customer">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <Settings2 className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Customer Settings</CardTitle>
                  <CardDescription>Configure customer tiers and auto-tagging rules.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/loyalty">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <Gift className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Loyalty Settings</CardTitle>
                  <CardDescription>Configure loyalty earn, redeem and expiry rules.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/coupons">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <TicketPercent className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Coupons</CardTitle>
                  <CardDescription>Create and manage discount coupons for campaigns.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/invoice-promotions">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <FileText className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Invoice Promotions</CardTitle>
                  <CardDescription>Manage invoice banners and DOB/anniversary reward rules.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/email-templates">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <Mail className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Email Templates</CardTitle>
                  <CardDescription>Connect Zoho Mail and manage invoice/certificate email templates.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/message-templates">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <MessageSquare className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>WhatsApp Templates</CardTitle>
                  <CardDescription>Manage WhatsApp/Web templates for CRM campaigns.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/ebay-settings">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <ImageIcon className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>eBay Settings</CardTitle>
                  <CardDescription>Configure category-specific images for eBay product descriptions.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>

            <LoadingLink href="/settings/marketplaces">
              <Card className="hover:bg-muted/50 transition-colors cursor-pointer h-full">
                <CardHeader>
                  <Store className="h-8 w-8 mb-2 text-primary" />
                  <CardTitle>Marketplace Settings</CardTitle>
                  <CardDescription>Configure marketplace fee schedules, margins and pricing profiles.</CardDescription>
                </CardHeader>
              </Card>
            </LoadingLink>
          </div>
        }
        company={
            <Card>
                <CardHeader>
                    <CardTitle>Company Profile</CardTitle>
                    <CardDescription>Manage your company details and logo.</CardDescription>
                </CardHeader>
                <CardContent>
                    <CompanySettingsForm initialData={companySettings} />
                </CardContent>
            </Card>
        }
        landingPage={
            <LandingPageForm initialSettings={landingPageSettings as ExtendedLandingPageSettings} />
        }
        general={
          <Card>
            <CardHeader>
              <CardTitle>Quick Settings</CardTitle>
              <CardDescription>Commonly used system parameters.</CardDescription>
            </CardHeader>
            <CardContent>
              <SettingsForm config={config} />
            </CardContent>
          </Card>
        }
        advanced={
           <Card>
              <CardHeader>
                <Settings2 className="h-8 w-8 mb-2 text-primary" />
                <CardTitle>Advanced Configuration</CardTitle>
                <CardDescription>System-level parameters and environment variables (Read-only).</CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {settings.map((setting: { key: string; value: string; description: string | null }) => (
                  <div key={setting.key} className="grid grid-cols-2 gap-4 p-4 border rounded-lg">
                    <div className="space-y-1">
                      <p className="font-medium">{setting.key}</p>
                      {setting.description && (
                        <p className="text-sm text-muted-foreground">{setting.description}</p>
                      )}
                    </div>
                    <div className="font-mono text-sm break-all">{setting.value}</div>
                  </div>
                ))}
              </CardContent>
           </Card>
        }
      />
    </div></AnimatedPage>
  );
}
